  "<svg width=\"36\" height=\"36\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"1.5\" style=\"margin-bottom:8px\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"18\" rx=\"3\"/><circle cx=\"7\" cy=\"8\" r=\"1\" fill=\"var(--gold)\"/><circle cx=\"12\" cy=\"8\" r=\"1\" fill=\"var(--gold)\"/><circle cx=\"17\" cy=\"8\" r=\"1\" fill=\"var(--gold)\"/><line x1=\"2\" y1=\"11\" x2=\"22\" y2=\"11\"/></svg>": "<svg width=\"36\" height=\"36\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"1.5\" style=\"margin-bottom:8px\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"18\" rx=\"3\"/><circle cx=\"7\" cy=\"8\" r=\"1\" fill=\"var(--gold)\"/><circle cx=\"12\" cy=\"8\" r=\"1\" fill=\"var(--gold)\"/><circle cx=\"17\" cy=\"8\" r=\"1\" fill=\"var(--gold)\"/><line x1=\"2\" y1=\"11\" x2=\"22\" y2=\"11\"/></svg>",
  "<h3 style=\"margin:0 0 6px;font-size:16px;color:var(--text);\">Switch to Board Mode</h3>": "<h3 style=\"margin:0 0 6px;font-size:16px;color:var(--text);\">Cambiar a modo pizarra</h3>",
  "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.</p>": "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">Se abrirá una página nueva como pizarra. Puedes dibujar, añadir formas, notas adhesivas y conectores libremente por todo el lienzo.</p>",
  "<button id=\"board-confirm-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;\">Cancel</button>": "<button id=\"board-confirm-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;\">Cancelar</button>",
  "<button id=\"board-confirm-ok\" style=\"padding:8px 18px;border-radius:8px;border:none;background:var(--gold);color:#111;font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;\">Open Board</button>": "<button id=\"board-confirm-ok\" style=\"padding:8px 18px;border-radius:8px;border:none;background:var(--gold);color:#111;font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;\">Abrir pizarra</button>",
  "background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:28px 32px;max-width:420px;width:90%;text-align:center;box-shadow:0 12px 40px rgba(0,0,0,0.5);": "background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:28px 32px;max-width:420px;width:90%;text-align:center;box-shadow:0 12px 40px rgba(0,0,0,0.5);",
  "<h3 style=\"margin:0 0 6px;font-size:16px;color:var(--text);\">Board Already Exists</h3>": "<h3 style=\"margin:0 0 6px;font-size:16px;color:var(--text);\">La pizarra ya existe</h3>",
  "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">There is already an open board ": "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">Ya hay una pizarra abierta ",
  "<button id=\"board-choice-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;white-space:nowrap;\">Cancel</button>": "<button id=\"board-choice-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;white-space:nowrap;\">Cancelar</button>",
  "<button id=\"board-choice-switch\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--gold);background:transparent;color:var(--gold);font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;white-space:nowrap;\">Go to Existing Board</button>": "<button id=\"board-choice-switch\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--gold);background:transparent;color:var(--gold);font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;white-space:nowrap;\">Ir a la pizarra existente</button>",
