  "<span>First assign a Design Field to at least one object in the design (right panel), then AI will fill them.</span></div></div>": "<span>Primero asigna un campo de diseño a al menos un objeto del diseño (panel derecho) y la IA los rellenará.</span></div></div>",
  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "Esta solicitud proviene del Generador masivo (fase PLAN). Lee la instrucción y los campos de diseño y, después, ENUMERA las salidas que producirás, SOLO LAS ETIQUETAS (sin contenido de campos). Devuelve SOLO un objeto JSON sin formato: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. Cuando translate sea true, las etiquetas son los NOMBRES DE LOS IDIOMAS (escritos en el mismo idioma que usó el usuario). De lo contrario, las etiquetas son un tema/semilla breve y distinto para cada salida. Respeta cualquier cantidad indicada en la instrucción; si no, usa un conjunto razonable (entre 6 y 12). Límite estricto: 500.\n",
