  "Create your dika studio account": "Crea tu cuenta de dika studio",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way.": "Una cuenta desbloquea la biblioteca online de plantillas y recursos, además de las novedades. El editor funciona igual de cualquier forma.",
  "This app could not reach dika studio just now, so the full sign-up flow is not available.": "La aplicación no pudo conectarse con dika studio en este momento, por lo que el flujo completo de registro no está disponible.",
  "You can carry on using the editor: everything except the online library works offline.": "Puedes seguir usando el editor: todo funciona sin conexión salvo la biblioteca en línea.",
  "It will ask again next time you open it.": "Volverá a preguntarlo la próxima vez que lo abras.",
  "Registration wizard": "Asistente de registro",
  "<div style=\"font-size:28px;font-weight:700;color:var(--text);margin-bottom:4px\">dika studio</div>": "<div style=\"font-size:28px;font-weight:700;color:var(--text);margin-bottom:4px\">dika studio</div>",
  "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Multi-Product Design Platform</div>": "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Plataforma de diseño multiproducto</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Version 2.0</div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Version 2.0</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Built by <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Creado por <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">&copy; 2026 Mirex Agency. Released under the Business Source License 1.1.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">&copy; 2026 Mirex Agency. Publicado bajo Business Source License 1.1.</div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Reset clears only the wizard's own record. Your projects, settings and keys are untouched.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Restablecer elimina solo el registro del asistente. Tus proyectos, ajustes y claves no se modifican.</div>",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Need help? Contact us:</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">¿Necesitas ayuda? Contacta con nosotros:</p>",
  "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visit our website</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visita nuestro sitio</a></div>",
  "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Email support@dika.studio</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Envía un correo a support@dika.studio</a></div>",
