  "Video editor": "Editor de vídeo",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Tiempos de guardado automático de este navegador. El estado más reciente se almacena en <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; las instantáneas rotativas usan <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>",
  "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">Aún no hay ninguna entrada de <code>dika_autosave</code>.</p>",
  "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Clears stored version snapshots (<code>dika_versions</code>). Current canvas and latest auto-save file are not removed.</span>": "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Borra las instantáneas de versiones guardadas (<code>dika_versions</code>). No se eliminan el lienzo actual ni el último archivo de guardado automático.</span>",
