  "No folders yet. Click the button above to create one.": "Aún no hay carpetas. Haz clic en el botón de arriba para crear una.",
  "No images uploaded yet.": "Aún no se han subido imágenes.",
  "Products, categories, brands and attributes come from the dika studio product catalogue.": "Los productos, categorías, marcas y atributos provienen del catálogo de productos de dika studio.",
  "This is the offline Community Edition, so there is no catalogue to read from.": "Esta es la Community Edition sin conexión, por lo que no hay ningún catálogo que consultar.",
  "Paint Tool": "Herramienta de pintura",
  "Board Settings": "Configuración de pizarra",
  "Brush Size": "Tamaño del pincel",
  "Brush Color": "Color del pincel",
  "Switch to Board Mode": "Cambiar al modo Tablero",
  "A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.": "Se abrirá una página nueva como pizarra. Puedes dibujar, añadir formas, notas adhesivas y conectores libremente por todo el lienzo.",
  "Open Board": "Abrir tablero",
  "Profile": "Perfil",
