  "Radial Menu": "Menú radial",
  "Left Menu Organization": "Organización del menú izquierdo",
  "Show or hide items in the left sidebar rail.": "Mostrar u ocultar elementos en la barra lateral izquierda.",
  "Show All": "Mostrar todo",
  "Hide All": "Ocultar todo",
  "General": "General",
  "Trash Auto-Clean": "Limpieza automática de la papelera",
  "Danger Zone": "Zona de peligro",
