  "Stil": "Estilo",
  "Add products from the panel's Assets > Products section, and they'll appear here automatically.": "Añade productos desde la sección Activos > Productos del panel y aparecerán aquí automáticamente.",
  "A design and video studio that runs on this machine.": "Un estudio de diseño y video que funciona en este equipo.",
  "Your work stays here. Documents, media and version history never leave this computer.": "Tu trabajo se queda aquí. Los documentos, recursos multimedia y el historial de versiones nunca salen de este equipo.",
  "Free to use. Source available under the Business Source License 1.1.": "Uso gratuito. Código fuente disponible bajo la Business Source License 1.1.",
  "Your projects are stored in this browser profile. That is the only copy.": "Tus proyectos se guardan en este perfil del navegador. Esa es la única copia.",
  "Clearing site data deletes them. So does a different browser, or a fresh profile.": "Al borrar los datos del sitio, se eliminan. Lo mismo ocurre con otro navegador o un perfil nuevo.",
  "Export a project file for anything you want to keep. It carries the design and its media, and it opens on any machine.": "Exporta un archivo de proyecto para conservar lo que quieras. Incluye el diseño y sus recursos multimedia, y se abre en cualquier equipo.",
  "Export a project file now": "Exportar ahora un archivo de proyecto",
  "Remind me to export": "Recordarme exportar",
  "Never": "Nunca",
  "Weekly": "Semanal",
  "Monthly": "Mensual",
  "That is everything. Your work stays on this machine.": "Eso es todo. Tu trabajo permanece en este equipo.",
  "You can reopen this from Settings > About.": "Puedes volver a abrirlo desde Configuración > Acerca de.",
  "Start using it": "Empezar a usarlo",
  "Your profile data is used in contact presets and bulk export.": "Tus datos de perfil se usan en ajustes preestablecidos de contacto y en la exportación masiva.",
  "JOB TITLE": "PUESTO",
  "ADDRESS": "DIRECCIÓN",
  "Social Media": "Redes sociales",
  "Save Profile": "Guardar perfil",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way, online or offline.": "Una cuenta desbloquea la biblioteca online de plantillas y recursos, además de las novedades. El editor funciona igual online o sin conexión.",
  "Sign in to unlock:": "Inicia sesión para desbloquear:",
  "The online template and asset library": "La biblioteca de plantillas y recursos en línea",
  "Release news and early access to new features": "Noticias de lanzamientos y acceso anticipado a nuevas funciones",
  "The editor itself works either way, with or without an account, online or offline.": "El editor funciona igual con o sin cuenta, tanto en línea como sin conexión.",
  "Create an account": "Crear una cuenta",
  "WHAT THIS APP SENDS": "QUÉ ENVÍA ESTA APLICACIÓN",
  "Once a day: an install id, the app version, your platform and language, and your account id once you sign in.": "Una vez al día: un ID de instalación, la versión de la aplicación, tu plataforma e idioma y, cuando inicias sesión, tu ID de cuenta.",
  "Nothing about your designs. No document, no title, no file name, no image.": "Nada sobre tus diseños. Sin documento, título, nombre de archivo ni imagen.",
  "WHERE THE SESSION IS KEPT": "DÓNDE SE GUARDA LA SESIÓN",
  "You are running the browser build, where every local page shares one storage area, so another local file opened in this browser could read this session. It is therefore short-lived (about 24 hours) and can only read the template library. The desktop app keeps its own isolated storage.": "Estás usando la versión del navegador, donde todas las páginas locales comparten un área de almacenamiento, por lo que otro archivo local abierto en este navegador podría leer esta sesión. Por eso la sesión dura poco (unas 24 horas) y solo puede leer la biblioteca de plantillas. La aplicación de escritorio mantiene su propio almacenamiento aislado.",
  "Your own keys for the stock media providers. They fill the Images and Audio search tabs, and the GIFs and Stickers tabs in Items. Every provider below has a free tier.": "Tus propias claves para los proveedores de recursos multimedia de stock. Completan las pestañas Imágenes y Audio, y las pestañas GIF y Pegatinas de Elementos. Todos los proveedores siguientes tienen un nivel gratuito.",
  "These keys are stored in this browser only, and this build never sends them anywhere except to the provider itself. Anyone with access to this computer or its browser profile can read them, so use a restricted key with the lowest quota you need.": "Estas claves solo se almacenan en este navegador y esta versión nunca las envía a ningún sitio salvo al propio proveedor. Cualquier persona con acceso a este equipo o al perfil de su navegador puede leerlas, así que usa una clave restringida con la cuota mínima que necesites.",
  "Save keys": "Guardar claves",
  "1. Go to unsplash.com/oauth/applications and create an app": "1. Ve a unsplash.com/oauth/applications y crea una aplicación",
  "2. Copy the Access Key, not the Secret Key": "2. Copia la clave de acceso, no la clave secreta",
  "Header: Authorization: Client-ID YOUR_KEY - 50 req/hr on demo, 5000 req/hr in production": "Encabezado: Authorization: Client-ID YOUR_KEY - 50 solicitudes/h en la demo, 5000 solicitudes/h en producción",
  "1. Go to pexels.com/api and request a key": "1. Ve a pexels.com/api y solicita una clave",
  "2. It is issued instantly": "2. Se emite al instante",
  "Header: Authorization: YOUR_KEY - 200 req/hr, 20K req/month": "Encabezado: Authorization: YOUR_KEY - 200 solicitudes/h, 20K solicitudes/mes",
  "1. Go to pixabay.com/api/docs/ and sign up": "1. Ve a pixabay.com/api/docs/ y regístrate",
  "2. Copy the key shown on the docs page": "2. Copia la clave que aparece en la página de documentación",
  "500K+ CC-licensed sound effects - header: Authorization: Token YOUR_KEY": "Más de 500K efectos de sonido con licencia CC - encabezado: Authorization: Token YOUR_KEY",
  "1. Go to freesound.org/apiv2/apply and create an API app": "1. Ve a freesound.org/apiv2/apply y crea una aplicación de API",
  "2. Copy the API Token": "2. Copia el token de API",
  "1. Go to devportal.jamendo.com and register an app": "1. Ve a devportal.jamendo.com y registra una aplicación",
  "2. Copy the Client ID": "2. Copia el ID de cliente",
  "1. Go to developers.giphy.com and create an app": "1. Ve a developers.giphy.com y crea una aplicación",
  "2. Copy the API Key": "2. Copia la clave de API",
