  "Auto-save times from this browser. The latest state is stored under dika_autosave; rolling snapshots use dika_versions.": "Tiempos de guardado automático de este navegador. El estado más reciente se almacena en dika_autosave; las instantáneas rotativas usan dika_versions.",
  "Clear History": "Borrar historial",
  "Customize shortcuts, manage profiles, and resolve conflicts across all app modules.": "Personaliza los atajos, gestiona los perfiles y resuelve conflictos en todos los módulos de la aplicación.",
  "All Categories": "Todas las categorías",
