  "Sound Effects": "Efectos de sonido",
  "Skip Startup Wizard": "Omitir el asistente de inicio",
  "In multi-page projects, to keep the app fast, pages you haven't opened for a long time are put to sleep in the background. Their content is safely stored and instantly returns when you click its tab. The page you're working on, a few nearby pages, and video / infinite canvas / slide / board pages always stay open.": "En proyectos de varias páginas, para mantener la aplicación rápida, las páginas que no has abierto durante mucho tiempo se ponen en suspensión en segundo plano. Su contenido se almacena de forma segura y vuelve al instante al hacer clic en su pestaña. La página en la que trabajas, algunas páginas cercanas y las páginas de vídeo, lienzo infinito, diapositivas y tablero siempre permanecen abiertas.",
  "Automatic sleep": "Suspensión automática",
  "Maximum awake pages (pages older than this number sleep)": "Máximo de páginas activas (las páginas anteriores a este número se suspenden)",
  "Neighbor window (pages kept awake on each side of the active page)": "Ventana vecina (las páginas a cada lado de la activa permanecen abiertas)",
